use verus::prelude::*;

// Function: replace_blanks_with_chars
// Given an input vector of characters `str1` and a character `ch`,
// returns a new vector where every ASCII space (' ') in `str1` is
// replaced by `ch`, and all other characters are left unchanged.
// The result has the same length as `str1`.
//
// Specification:
//   - postcondition: result.len() == str1.len()
//   - for all 0 <= i < str1.len():
//       if str1[i] == ' ' then result[i] == ch
//       else                 result[i] == str1[i]
verus! {
    fn replace_blanks_with_chars(str1: &Vec<char>, ch: char) -> Vec<char> {
        // No preconditions
        requires(true);
        // Postconditions on the result
        ensures(|res: Vec<char>| 
            res.len() == str1.len() &&
            forall(|i: int| 
                0 <= i && i < str1.len() as int
                ==> (if str1[i as usize] == ' ' {
                        res[i as usize] == ch
                    } else {
                        res[i as usize] == str1[i as usize]
                    })
            )
        );

        // Implementation via a simple loop building a fresh vector.
        let mut res: Vec<char> = Vec::new();
        let n: usize = str1.len();
        res.reserve(n);

        let mut i: usize = 0;
        // Loop over all indices
        while i < n {
            // Invariants to help the verifier:
            // 1) i is within bounds
            invariant(i <= n);
            // 2) We've pushed exactly i elements so far
            invariant(res.len() == i);
            // 3) For every index j < i, res[j] satisfies the postcondition
            invariant(forall(|j: int| 
                0 <= j && j < i as int
                ==> (if str1[j as usize] == ' ' {
                        res[j as usize] == ch
                    } else {
                        res[j as usize] == str1[j as usize]
                    })
            ));
            decreases(n - i);

            let c = str1[i];
            if c == ' ' {
                res.push(ch);
            } else {
                res.push(c);
            }
            i += 1;
        }

        // By the invariants, res.len() == n and each position satisfies the condition.
        res
    }
}

